custom_css:
/* ==========================================================================
   First Search Marketing - Elementor Site Settings > Custom CSS
   Adds what Elementor can't do natively: gradient borders and text, glows,
   pills, stage logos, tabs, FAQ, overlaps. Colours read your Global Colors.
   ========================================================================== */

/* ---------- 1. Brand tokens ----------
   Every colour and font here reads from Elementor's Site Settings (Global Colors / Global Fonts),
   with the brand value as a fallback. Change a Global Color in Elementor and this CSS follows it. */
:root {
  --fs-purple: var(--e-global-color-primary, #250762);        /* Primary */
  --fs-sky: var(--e-global-color-secondary, #3299D5);         /* Secondary */
  --fs-ink: var(--e-global-color-text, #1C1B22);              /* Text */
  --fs-royal: var(--e-global-color-accent, #174FA2);          /* Accent */
  --fs-body: var(--e-global-color-fsbody, #2F2E36);
  --fs-muted: var(--e-global-color-fsmuted, #6B6A72);
  --fs-sky-ink: var(--e-global-color-fsskyink, #1F78B4);
  --fs-aqua: var(--e-global-color-fsaqua, #72CCD8);
  --fs-purple-deep: var(--e-global-color-fsdeep, #1A0446);
  --fs-grey: var(--e-global-color-fsgrey, #D9D8D7);
  --fs-line: var(--e-global-color-fsline, #E3E2EA);
  --fs-tint: var(--e-global-color-fstint, #EEF0F9);
  --fs-soft: var(--e-global-color-fssoft, #F4F4F6);

  --fs-grad: linear-gradient(90deg, var(--fs-aqua) 0%, var(--fs-royal) 100%);
  --fs-grad-diag: linear-gradient(120deg, var(--fs-aqua) 0%, var(--fs-royal) 100%);
  --fs-grad-text: linear-gradient(90deg, var(--fs-aqua) 0%, var(--fs-sky) 45%, var(--fs-royal) 100%);
  --fs-grad-purple: linear-gradient(135deg, #2B0A80 0%, var(--fs-purple) 55%, #200556 100%);
  --fs-grad-purple-hover: linear-gradient(135deg, #300C8C 0%, #2A0874 100%);
  --fs-glow: radial-gradient(90% 80% at 100% 0%, rgba(50, 153, 213, .5) 0%, transparent 60%);

  --fs-font: var(--e-global-typography-primary-font-family, "Poppins"), system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
  --fs-font-ui: var(--e-global-typography-accent-font-family, "Inter"), system-ui, -apple-system, "Segoe UI", Arial, sans-serif;

  --fs-shadow-card: 0 18px 40px -18px rgba(37, 7, 98, .28);
  --fs-shadow-btn: 0 0 0 1px rgba(114, 204, 216, .35), 0 10px 22px -8px rgba(50, 153, 213, .55);
  --fs-shadow-btn-hover: 0 0 0 3px rgba(114, 204, 216, .35), 0 14px 28px -8px rgba(50, 153, 213, .65);
}

/* ---------- 2. Base type ---------- */
body {
  font-family: var(--fs-font);
  color: var(--fs-ink);
  background-color: var(--e-global-color-fsbg, #F8F7F7);   /* page background, as in the HTML */
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3, h4, h5, h6,
.elementor-heading-title {
  font-family: var(--fs-font);
  color: var(--fs-purple);
  letter-spacing: -0.015em;
}
h1.elementor-heading-title { font-weight: 700; font-size: clamp(40px, 5vw, 72px); line-height: 1.04; letter-spacing: -0.025em; }
h2.elementor-heading-title { font-weight: 700; font-size: clamp(32px, 3.9vw, 56px); line-height: 1.08; }
h3.elementor-heading-title { font-weight: 700; font-size: clamp(22px, 2vw, 28px); line-height: 1.2; }
::selection { background: rgba(114, 204, 216, .35); }

/* Text on dark sections */
.fs-dark h1, .fs-dark h2, .fs-dark h3, .fs-dark h4,
.fs-dark .elementor-heading-title { color: #fff; }
.fs-dark, .fs-dark .elementor-widget-text-editor { color: rgba(255, 255, 255, .9); }

/* Gradient words inside a heading: span.fs-gt "..." */
.fs-gt {
  color: transparent;
  background: var(--fs-grad-text);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}
/* Sky-blue words (the footer tagline style): span.fs-sky "business first." */
.fs-sky { color: var(--fs-sky); }

/* Eyebrow above a heading (add to a Heading or Text widget) */
.fs-eyebrow .elementor-heading-title,
.fs-eyebrow, .fs-eyebrow p {
  font-family: var(--fs-font);
  font-size: clamp(16px, 1.35vw, 20px);
  font-weight: 600;
  letter-spacing: 0;
  line-height: 1.3;
  color: var(--fs-sky);
  margin: 0;
}

/* Short aqua rule under a page title (add fs-h1-rule to the H1 Heading widget) */
.fs-h1-rule .elementor-heading-title::after {
  content: "";
  display: block;
  width: clamp(96px, 10vw, 140px);
  height: 4px;
  margin-top: clamp(18px, 2vw, 26px);
  border-radius: 2px;
  background: var(--fs-aqua);
}
/* Centered title: add both fs-h1-rule and fs-center */
.fs-center.fs-h1-rule .elementor-heading-title::after { margin-inline: auto; }

/* Hero paragraph */
.fs-hero-lead, .fs-hero-lead p {
  font-size: clamp(18px, 1.55vw, 22px);
  line-height: 1.45;
  max-width: 42ch;
  color: var(--fs-ink);
}

/* No trailing space under the last paragraph of a Text Editor (as in the HTML) */
.elementor-widget-text-editor p:last-child { margin-bottom: 0; }

/* ---------- 3. Links ---------- */
.elementor-widget-text-editor a:not(.elementor-button) {
  color: var(--fs-sky-ink);
  text-decoration: underline;
  text-underline-offset: 3px;
}
/* Italic underlined text link (the secondary link next to a button) */
.fs-link-u .elementor-button,
.fs-link-u a,
a.fs-link-u {
  display: inline !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: none !important;
  box-shadow: none !important;
  font-family: var(--fs-font);
  font-style: italic;
  font-weight: 500;
  font-size: 18px;
  color: var(--fs-purple) !important;
  text-decoration: underline !important;
  text-decoration-color: var(--fs-aqua) !important;
  text-decoration-thickness: 2px !important;
  text-underline-offset: 7px;
}
.fs-link-u .elementor-button:hover, .fs-link-u a:hover, a.fs-link-u:hover {
  color: var(--fs-royal) !important;
  text-decoration-color: var(--fs-royal) !important;
  transform: none;
}
.fs-dark .fs-link-u .elementor-button, .fs-dark .fs-link-u a { color: #fff !important; }

/* ---------- 4. Buttons ---------- */
/* Every button, every state: the gradient fills the whole button including its border and never repeats
   (otherwise the end of the gradient shows as a thin strip down the left edge on hover). */
.elementor-button, .elementor-button:hover, .elementor-button:focus, .elementor-button:focus-visible, .elementor-button:active,
.elementor-button-wrapper .elementor-button, .e-n-menu .elementor-button {
  background-origin: border-box !important;
  background-clip: border-box !important;
  background-size: 100% 100% !important;
  background-repeat: no-repeat !important;
}
[class*="elementor-kit-"] .elementor-button,
.elementor-button {
  font-family: var(--fs-font);
  font-weight: 600;
  font-size: 18px;
  letter-spacing: .005em;
  line-height: 1.2;
  padding: 16px 30px;
  border: 2px solid #4AA6DC;
  border-radius: 10px;
  color: #fff;
  background: var(--fs-grad-purple);
  background-origin: border-box;
  background-clip: border-box;
  box-shadow: var(--fs-shadow-btn);
  text-shadow: none;
  text-decoration: none;
  transition: background .2s ease, box-shadow .2s ease, transform .2s ease;
}
[class*="elementor-kit-"] .elementor-button:hover,
.elementor-button:hover,
.elementor-button:focus-visible {
  color: #fff;
  background: var(--fs-grad);
  border-color: transparent;
  box-shadow: 0 14px 30px -12px rgba(23, 79, 162, .55);
  transform: translateY(-2px);
}
.elementor-button:focus-visible { outline: 3px solid var(--fs-aqua); outline-offset: 3px; }

/* Gradient button: use on purple sections, cards and banners */
.fs-dark .elementor-button,
.fs-btn-grad .elementor-button {
  border-color: transparent;
  background: var(--fs-grad);
  text-shadow: 0 1px 2px rgba(20, 30, 80, .3);
  box-shadow: 0 14px 30px -12px rgba(23, 79, 162, .5);
}
.fs-dark .elementor-button:hover,
.fs-btn-grad .elementor-button:hover {
  background: linear-gradient(90deg, #7AD4DF 0%, #1C5BB5 100%);
  box-shadow: 0 18px 34px -12px rgba(23, 79, 162, .6);
}
/* White button: on the gradient banner / footer CTA */
.fs-btn-white .elementor-button {
  border-color: transparent;
  background: #fff;
  color: var(--fs-purple);
  box-shadow: 0 14px 30px -14px rgba(16, 12, 48, .45);
}
.fs-btn-white .elementor-button:hover { background: #fff; color: var(--fs-royal); }
/* Large button */
.fs-btn-lg .elementor-button { font-size: clamp(19px, 1.6vw, 22px); padding: 18px 36px; border-radius: 16px; }

/* ---------- 5. Sections (add to a Container) ---------- */
/* Light geometric background: upload bg-geometric.jpg to the Media Library,
   then set it as the container's Background image (Cover, Center).
   This class adds the fallback colour and spacing. */
.fs-geo { background-color: var(--fs-soft); }
.fs-section { padding-block: clamp(80px, 9vw, 130px); }

/* Purple section with the soft blue glow (How it works, framework, CTAs) */
.fs-dark {
  background: var(--fs-glow), var(--fs-grad-purple);
  color: #fff;
}
/* Purple block with rounded top corners (the framework / coaching blocks) */
.fs-dark-round { border-radius: 56px; overflow: hidden; }
@media (max-width: 767px) { .fs-dark-round { border-radius: 32px; } }

/* Gradient band (stats band, gradient CTA banner) */
.fs-grad { background: var(--fs-grad); color: #fff; }
.fs-grad .elementor-heading-title, .fs-grad .elementor-widget-text-editor { color: #fff; }

/* Header: gradient stripe under the header (add to an empty Container or Divider, 8-14px tall) */
.fs-stripe { height: 10px; min-height: 0; padding: 0; background: var(--fs-grad); }

/* ---------- 6. Cards ---------- */
/* Gradient-border card: white inside, aqua -> blue frame (add to a Container) */
.fs-gcard {
  --fs-bw: 6px;
  border: var(--fs-bw) solid transparent !important;
  border-radius: 32px !important;
  background: linear-gradient(#fff, #fff) padding-box, var(--fs-grad-diag) border-box !important;
  box-shadow: var(--fs-shadow-card);
}
.fs-gcard--thin { --fs-bw: 4px; border-radius: 24px !important; }
.fs-gcard--hover { transition: transform .2s ease, box-shadow .2s ease; }
.fs-gcard--hover:hover { transform: translateY(-4px); box-shadow: 0 26px 46px -22px rgba(37, 7, 98, .45); }

/* Purple card with a blue glow in the corner */
.fs-purple-card {
  border-radius: 32px;
  color: #fff;
  background: radial-gradient(380px 300px at 100% 100%, rgba(91, 186, 232, .7), transparent 70%), var(--fs-purple);
  box-shadow: var(--fs-shadow-card);
}
.fs-purple-card, .fs-purple-card .elementor-heading-title, .fs-purple-card .elementor-widget-text-editor { color: #fff; }

/* Soft grey box (callouts, metric boxes) */
.fs-soft-box { background: var(--fs-soft); border-radius: 18px; }

/* ---------- 7. Icon tiles (Icon Box / Image Box) ---------- */
/* White tile with the sky-blue ring and glow (core values, "Sound familiar?" cards) */
.fs-tile .elementor-icon,
.fs-tile .elementor-image-box-img img,
.fs-tile .elementor-icon-box-icon .elementor-icon {
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 0 0 4px var(--fs-sky), 0 0 20px 4px rgba(50, 153, 213, .55);
}
.fs-tile .elementor-image-box-img img { padding: 12px; }
/* Gradient icon colour for line icons on light backgrounds */
.fs-icon-grad .elementor-icon { color: var(--fs-sky); }
.fs-icon-grad .elementor-icon svg { fill: var(--fs-sky); }

/* ---------- 8. Pills ---------- */
.fs-pill {
  display: inline-flex;
  width: max-content;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 999px;
  background: var(--fs-tint);
  font-family: var(--fs-font-ui);
  font-size: 14px;
  font-weight: 600;
  color: var(--fs-purple);
  max-width: 100%;
  flex-wrap: wrap;
}
.fs-pill--purple { background: var(--fs-purple); color: #fff; }
/* Resource type pills (Loop Grid cards) */
.fs-type { display: inline-flex; width: max-content; padding: 4px 12px; border-radius: 999px; font-family: var(--fs-font); font-size: 12.5px; font-weight: 700; letter-spacing: .02em; color: #fff !important; }
.fs-type--blog { background: var(--fs-sky); }
.fs-type--case { background: var(--fs-purple); }
.fs-type--podcast { background: var(--fs-grad); }
.fs-type--video { background: var(--fs-royal); }

/* ---------- 9. FirstSearch stage logos ---------- */
/* span.fs-plogo "firstbrand"  (add fs-plogo--light on dark backgrounds) */
.fs-plogo {
  display: inline-flex;
  align-items: baseline;
  font-family: var(--fs-font);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1;
  text-transform: lowercase;
  white-space: nowrap;
  color: var(--fs-purple);
}
.fs-plogo b { font-weight: 800; color: #3299D5 !important; }   /* sub-brand blue: the same on every background, as in the design */
.fs-plogo--light { color: #fff; }
.fs-dark .fs-plogo-chip .fs-plogo, .fs-dark .fs-gcard .fs-plogo:not(.fs-plogo--light) { color: #250762; }
.fs-dark .fs-plogo-chip .fs-plogo b, .fs-dark .fs-gcard .fs-plogo:not(.fs-plogo--light) b { color: #3299D5; }
/* White chip around a stage logo (stage pills) */
.fs-plogo-chip { display: inline-flex; padding: 7px 16px 8px; border-radius: 999px; background: #fff; box-shadow: 0 8px 20px -12px rgba(37, 7, 98, .45); }

/* ---------- 10. Header menu (Nav Menu / Mega Menu widget: add fs-nav) ---------- */
.fs-nav .elementor-nav-menu--main .elementor-item,
.fs-nav .e-n-menu-title {
  font-family: var(--fs-font-ui);
  font-weight: 500;
  color: var(--fs-purple);
}
.fs-nav .elementor-nav-menu--main .elementor-item:hover,
.fs-nav .elementor-nav-menu--main .elementor-item.elementor-item-active,
.fs-nav .e-n-menu-title:hover { color: var(--fs-royal); }
/* Pointer: choose "Underline" in the widget, then this makes it the brand gradient */
.fs-nav .elementor-nav-menu--main .elementor-item::after { background: var(--fs-grad) !important; height: 2px; }
/* Dropdown panels */
.fs-nav .elementor-nav-menu--dropdown,
.fs-nav .e-n-menu-content > .e-con {
  border-radius: 18px;
  box-shadow: 0 24px 50px -18px rgba(28, 22, 72, .45);
  overflow: hidden;
}
.fs-nav .elementor-nav-menu--dropdown a:hover { background: var(--fs-tint); color: var(--fs-purple); }

/* ---------- 11. FAQ (Accordion widget: add fs-faq; icons set to plus / minus) ---------- */
.fs-faq .elementor-accordion-item, .fs-faq .elementor-toggle-item {
  position: relative; margin-bottom: 28px; border: 0 !important; border-radius: 18px; background: #fff; overflow: hidden;
  box-shadow: 0 12px 28px -20px rgba(28, 22, 72, .55);
}
.fs-faq .elementor-accordion-item::before, .fs-faq .elementor-toggle-item::before {
  content: ""; position: absolute; z-index: 1; left: 0; top: 0; bottom: 0; width: 5px; background: linear-gradient(180deg, var(--fs-aqua), var(--fs-royal));
}
.fs-faq .elementor-tab-title { display: flex; align-items: center; gap: 30px; padding: 24px 40px !important; border: 0 !important; cursor: pointer; }
.fs-faq .elementor-tab-title:hover .elementor-accordion-title { color: var(--fs-royal); }
.fs-faq .elementor-tab-title.elementor-active { background: var(--fs-purple); }
.fs-faq .elementor-tab-title.elementor-active a, .fs-faq .elementor-tab-title.elementor-active:hover a { color: #fff; }
.fs-faq .elementor-item-active, .fs-faq .elementor-accordion-item:has(.elementor-active) { box-shadow: 0 20px 40px -22px rgba(28, 22, 72, .6); }
/* the round + / - button */
.fs-faq .elementor-accordion-icon, .fs-faq .elementor-toggle-icon {
  position: relative; flex: none; float: none !important; width: 56px; height: 56px; border-radius: 50%; background: var(--fs-grad-diag); order: -1;
}
.fs-faq .elementor-accordion-icon > *, .fs-faq .elementor-toggle-icon > * { display: none !important; }
.fs-faq .elementor-accordion-icon::before, .fs-faq .elementor-accordion-icon::after,
.fs-faq .elementor-toggle-icon::before, .fs-faq .elementor-toggle-icon::after {
  content: ""; position: absolute; left: 50%; top: 50%; width: 22px; height: 3px; margin: -1.5px 0 0 -11px; border-radius: 2px; background: #fff; transition: transform .25s ease;
}
.fs-faq .elementor-accordion-icon::after, .fs-faq .elementor-toggle-icon::after { transform: rotate(90deg); }
.fs-faq .elementor-active .elementor-accordion-icon, .fs-faq .elementor-active .elementor-toggle-icon { background: #fff; }
.fs-faq .elementor-active .elementor-accordion-icon::before, .fs-faq .elementor-active .elementor-accordion-icon::after,
.fs-faq .elementor-active .elementor-toggle-icon::before, .fs-faq .elementor-active .elementor-toggle-icon::after { background: var(--fs-purple); }
.fs-faq .elementor-active .elementor-accordion-icon::after, .fs-faq .elementor-active .elementor-toggle-icon::after { transform: rotate(0); }
.fs-faq .elementor-tab-content { padding: 24px 48px 30px 126px !important; border: 0 !important; }
.fs-faq .elementor-tab-content p:last-child { margin-bottom: 0; }
@media (max-width: 767px) {
  .fs-faq .elementor-tab-title { gap: 16px; padding: 18px 20px !important; }
  .fs-faq .elementor-accordion-icon, .fs-faq .elementor-toggle-icon { width: 42px; height: 42px; }
  .fs-faq .elementor-accordion-icon::before, .fs-faq .elementor-accordion-icon::after { width: 16px; margin-left: -8px; }
  .fs-faq .elementor-tab-content { padding: 18px 20px 22px 78px !important; }
}

/* ---------- 12. Forms (Elementor Pro Form widget) ---------- */
.elementor-form .elementor-field-group > label,
.elementor-form .elementor-field-label {
  font-family: var(--fs-font-ui);
  font-weight: 600;
  font-size: 15px;
  color: var(--fs-purple);
}
.elementor-form .elementor-field-textual,
.elementor-form select.elementor-field {
  min-height: 52px;
  padding: 12px 16px;
  border: 2px solid var(--fs-line);
  border-radius: 12px;
  background: #fff;
  font-family: var(--fs-font);
  font-size: 16px;
  color: var(--fs-ink);
  transition: border-color .15s ease, box-shadow .15s ease;
}
.elementor-form textarea.elementor-field-textual { min-height: 130px; }
.elementor-form .elementor-field-textual:focus,
.elementor-form select.elementor-field:focus {
  outline: none;
  border-color: var(--fs-aqua);
  box-shadow: 0 0 0 4px rgba(114, 204, 216, .3);
}
.elementor-form .elementor-field-type-acceptance,
.elementor-form .elementor-field-type-checkbox.fs-consent {
  padding: 14px 16px;
  border-radius: 14px;
  background: var(--fs-soft);
  font-size: 13.5px;
  line-height: 1.5;
}
.elementor-form input[type="checkbox"], .elementor-form input[type="radio"] { accent-color: var(--fs-royal); }
.elementor-form .elementor-message-danger, .elementor-form .elementor-error { color: #B42318; }
.elementor-form .elementor-message-success { color: var(--fs-purple); font-weight: 600; }

/* ---------- 13. Hero layout (add fs-hero to the hero's row Container) ---------- */
/* Text column flexes; media column (video / card) is 440px on desktop */
@media (min-width: 1025px) {
  .fs-hero { column-gap: clamp(40px, 4vw, 64px) !important; }
  .fs-hero > .e-con:last-child,
  .fs-hero > .elementor-element:last-child { flex: 0 0 440px !important; max-width: 440px; }
  .fs-hero > .e-con:first-child,
  .fs-hero > .elementor-element:first-child { flex: 1 1 0 !important; min-width: 0; }
}

/* ---------- 14. Media frames ---------- */
/* Video in a gradient frame (Video widget: add fs-video) */
.fs-video .elementor-wrapper,
.fs-video .elementor-custom-embed-image-overlay {
  border-radius: 36px;
  overflow: hidden;
}
.fs-video {
  padding: 6px;
  border-radius: 42px;
  background: var(--fs-grad-diag);
  box-shadow: var(--fs-shadow-card);
}
/* Image with rounded gradient frame (Image widget: add fs-img-frame) */
.fs-img-frame img { border-radius: 24px; padding: 4px; background: var(--fs-grad-diag); }

/* ---------- 15. Footer ---------- */
.fs-footer { background: radial-gradient(700px 420px at 0% 100%, rgba(50, 153, 213, .38), transparent 70%), radial-gradient(600px 360px at 100% 30%, rgba(124, 210, 211, .18), transparent 70%), var(--fs-purple) !important; color: #D8D6EE; }
.fs-footer a { color: #D8D6EE; }
.fs-footer a:hover { color: #fff; }
.fs-footer .elementor-heading-title { color: #fff; }
/* White box behind the full-colour logo in the footer */
.fs-logo-box { display: inline-block; padding: 12px 18px; border-radius: 18px; background: #fff; box-shadow: 0 0 0 3px rgba(50, 153, 213, .35), 0 0 28px 4px rgba(50, 153, 213, .35); }

/* ---------- 17. Header & footer templates (used by the importable templates) ---------- */
/* Header bar: white, shadow + shorter once sticky has kicked in */
.fs-header { background: #fff; transition: box-shadow .25s ease; z-index: 99; }
.fs-header.elementor-sticky--effects { box-shadow: 0 12px 30px -18px rgba(37, 7, 98, .45); }
.fs-header .fs-header-row { transition: min-height .25s ease; }
.fs-header.elementor-sticky--effects .fs-header-row { min-height: 84px !important; }
.fs-header .elementor-widget-theme-site-logo img { width: auto; max-height: 62px; transition: max-height .25s ease; }
.fs-header.elementor-sticky--effects .elementor-widget-theme-site-logo img { max-height: 50px; }

/* Menu widget (Elementor Pro "Menu"): titles */
.fs-nav .e-n-menu-title { padding: 8px 0 !important; border-bottom: 2px solid transparent; }
.fs-nav .e-n-menu-title-text, .fs-nav .e-n-menu-title-text a { font-family: var(--fs-font-ui); font-size: 18px; font-weight: 500; color: var(--fs-purple); }
.fs-nav .e-n-menu-title { position: relative; }
.fs-nav .e-n-menu-title::after {
  content: "" !important; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; border-radius: 2px; background: var(--fs-grad);
  transform: scaleX(0); transform-origin: left; transition: transform .2s ease; pointer-events: none;
}
.fs-nav .e-n-menu-title:hover::after, .fs-nav .e-n-menu-title.e-current::after, .fs-nav .e-n-menu-title:has([aria-expanded="true"])::after,
.fs-nav .e-n-menu-item:has(.e-n-menu-content.e-active) > .e-n-menu-title::after { transform: scaleX(1); }
@media (max-width: 1024px) { .fs-nav .e-n-menu-title::after { display: none; } }
.fs-nav .e-n-menu-title:hover .e-n-menu-title-text { color: var(--fs-royal); }
.fs-nav .e-n-menu-dropdown-icon { color: var(--fs-purple); }
/* Drop-down panels */
.fs-mega { background: #fff; border-radius: 22px; box-shadow: 0 30px 60px -24px rgba(28, 22, 72, .5); }
/* Links with a bold title and a one-line description */
.fs-menu-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
.fs-menu-list a { display: block; padding: 12px 14px; border-radius: 14px; text-decoration: none !important; transition: background .15s ease; }
.fs-menu-list a:hover { background: var(--fs-tint); }
.fs-menu-list b { display: block; font-family: var(--fs-font); font-size: 17px; font-weight: 700; color: var(--fs-purple); }
.fs-menu-list span { display: block; margin-top: 2px; font-family: var(--fs-font-ui); font-size: 14px; color: var(--fs-muted); }
/* What We Do: stage columns */
.fs-stage-link { display: block; padding: 10px 12px; border-radius: 14px; text-decoration: none !important; }
.fs-stage-link:hover { background: var(--fs-tint); }
.fs-stage-link .fs-plogo { font-size: 22px; }
.fs-stage-link small { display: block; margin-top: 4px; font-family: var(--fs-font-ui); font-size: 13.5px; color: var(--fs-muted); }
.fs-svc-list { list-style: none; margin: 6px 0 0; padding: 0; }
.fs-svc-list a { display: block; padding: 7px 12px; border-radius: 10px; font-family: var(--fs-font-ui); font-size: 15px; font-weight: 500; color: var(--fs-body) !important; text-decoration: none !important; }
.fs-svc-list a:hover { background: var(--fs-tint); color: var(--fs-purple) !important; }
/* What We Do: purple call-to-action card on the right of the panel */
.fs-mega-cta .fs-big { display: block; padding: 12px 0; border-bottom: 1px solid rgba(255, 255, 255, .18); font-family: var(--fs-font); font-size: 18px; font-weight: 700; color: #fff !important; text-decoration: none !important; }
.fs-mega-cta .fs-big span { display: block; font-family: var(--fs-font-ui); font-size: 13.5px; font-weight: 400; color: #C9C6EA; }
.fs-mega-cta .fs-big:hover { color: var(--fs-aqua) !important; }

/* Footer */
.fs-footer .fs-tagline .elementor-heading-title { font-size: clamp(22px, 2.2vw, 30px); font-weight: 700; line-height: 1.2; color: #fff; }
.fs-footer h4.elementor-heading-title, .fs-footer .fs-col-title .elementor-heading-title { font-size: 17px; font-weight: 700; color: #fff; }
.fs-footer .fs-col-title .elementor-heading-title::after { content: ""; display: block; width: 32px; height: 3px; margin-top: 10px; border-radius: 2px; background: var(--fs-grad); }
.fs-footer .elementor-icon-list-text { color: #D8D6EE; transition: color .15s ease; }
.fs-footer .elementor-icon-list-item a:hover .elementor-icon-list-text { color: #fff; }
.fs-footer .elementor-icon-list-icon i, .fs-footer .elementor-icon-list-icon svg { color: var(--fs-aqua); fill: var(--fs-aqua); }
.fs-footer .fs-news { padding: 24px 26px; border-radius: 22px; background: rgba(255, 255, 255, .06); border: 1px solid rgba(255, 255, 255, .12); }
.fs-footer .fs-news .elementor-field-textual { min-height: 50px; border-color: transparent; }
.fs-footer .fs-news .elementor-button { border-color: transparent; background: var(--fs-grad); }
.fs-footer .elementor-social-icon { background: rgba(255, 255, 255, .1) !important; border-radius: 50%; }
.fs-footer .elementor-social-icon:hover { background: var(--fs-grad) !important; }
.fs-footer .fs-bottom, .fs-footer .fs-bottom a { font-family: var(--fs-font-ui); font-size: 14px; color: #B9B5DA; }
.fs-footer .fs-bottom a:hover { color: #fff; }
.fs-footer .fs-stage-links a { display: inline-block; margin: 4px 0; text-decoration: none; }
.fs-footer .fs-stage-links .fs-plogo { font-size: 19px; }

/* ---------- 18. Page sections (used by the page templates) ---------- */
/* Section header: eyebrow + H2 + lead, centred */
.fs-sec-head { text-align: center; max-width: 880px; margin-inline: auto; }
.fs-lead { font-size: clamp(17px, 1.4vw, 20px); line-height: 1.55; color: var(--fs-body); }
.fs-dark .fs-lead { color: rgba(255, 255, 255, .88); }

/* Problem cards: purple row card with a white icon tile (Image Box, position left) */
.elementor-widget.fs-pcard { padding: 22px 26px; }
.fs-pcard { border-radius: 24px; background: var(--fs-purple); box-shadow: 0 22px 40px -24px rgba(28, 22, 72, .8); }
.fs-pcard .elementor-image-box-img img { background: #fff; border-radius: 16px; padding: 12px; box-shadow: 0 0 0 4px var(--fs-sky), 0 0 20px 4px rgba(50, 153, 213, .55); }
.fs-pcard .elementor-image-box-title { color: #fff; font-size: clamp(20px, 1.8vw, 26px); margin-bottom: 6px; }
.fs-pcard .elementor-image-box-description { color: rgba(255, 255, 255, .92); font-size: 17px; line-height: 1.45; }
.fs-close .elementor-heading-title { font-size: clamp(20px, 1.9vw, 26px); font-weight: 600; color: var(--fs-purple); }

/* "How it works" steps: big gradient number above a white card */
.fs-step { position: relative; }  /* padding is set on the container in Elementor */
.fs-step-num .elementor-heading-title { position: absolute; top: -78px; left: 50%; transform: translateX(-50%); font-size: 110px; font-weight: 800; line-height: 1; color: transparent; background: linear-gradient(180deg, #8FD5EE, var(--fs-sky) 55%, var(--fs-royal)); -webkit-background-clip: text; background-clip: text; }
.fs-step-num .elementor-heading-title { text-align: center; }
.fs-step-hl .elementor-heading-title:not(.fs-step-num *), .fs-step-hl .elementor-widget-text-editor { color: #fff; }
.fs-steps { padding-top: 90px; }
.fs-steps > .fs-step:not(:last-child)::after {
  content: ""; position: absolute; top: 130px; left: 100%; width: 56px; height: 0; border-top: 3px dashed rgba(255, 255, 255, .9);
  transform-origin: left; animation: fs-draw .35s ease both; animation-delay: calc(var(--fs-i, 0) * .35s + .6s);
}
.fs-steps > .fs-step:nth-child(1) { --fs-i: 0; } .fs-steps > .fs-step:nth-child(2) { --fs-i: 1; } .fs-steps > .fs-step:nth-child(3) { --fs-i: 2; }
@keyframes fs-draw { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@media (max-width: 1024px) { .fs-steps > .fs-step::after { display: none; } }

/* Stats band (Counter widget inside fs-grad) */
.fs-grad .elementor-counter-number-wrapper { font-family: var(--fs-font); font-weight: 800; font-size: clamp(48px, 5vw, 76px); color: #fff; }
.fs-grad .elementor-counter-title { font-family: var(--fs-font-ui); font-size: 17px; color: rgba(255, 255, 255, .92); }
.fs-dark .elementor-counter-number-wrapper { font-family: var(--fs-font); font-weight: 800; font-size: clamp(48px, 5vw, 72px); color: #fff; }
.fs-dark .elementor-counter-title { font-family: var(--fs-font-ui); color: rgba(255, 255, 255, .88); }

/* Before -> after table (HTML widget: ) */
.fs-table { width: 100%; border-collapse: separate; border-spacing: 0; overflow: hidden; border-radius: 14px; background: #fff; font-family: var(--fs-font); }
.fs-table th, .fs-table td { padding: 14px 16px; border-bottom: 1px solid var(--fs-line); text-align: left; color: var(--fs-purple); font-size: 17px; }
.fs-table thead th { font-size: 13px; letter-spacing: .04em; text-transform: uppercase; background: #fff; }
.fs-table thead th.b { background: var(--fs-purple); color: #fff; text-align: center; }
.fs-table thead th.a { background: var(--fs-grad); color: #fff; text-align: center; }
.fs-table tbody th { background: #F4F4F6; font-weight: 600; }
.fs-table td.b { text-align: center; font-weight: 600; }
.fs-table td.ar { width: 44px; text-align: center; color: var(--fs-sky); background: #F4F4F6; }
.fs-table td.a { text-align: center; font-weight: 800; color: #fff; background: var(--fs-grad); }
.fs-table tr:last-child th, .fs-table tr:last-child td { border-bottom: 0; }
@media (max-width: 767px) {
  .fs-table th, .fs-table td { padding: 10px 8px; font-size: 14px; }
  .fs-table thead th { font-size: 11px; letter-spacing: .02em; }
  .fs-table td.ar { width: 24px; padding: 10px 2px; }
}

/* Review cards */

/* Check pills (Icon List widget): purple pills with a sky check */
.fs-check-pills .elementor-icon-list-items { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.fs-check-pills .elementor-icon-list-item { padding: 12px 16px !important; margin: 0 !important; border-radius: 14px; background: var(--fs-purple); }
.fs-check-pills .elementor-icon-list-text { color: #fff; font-weight: 500; }
.fs-check-pills .elementor-icon-list-item { align-items: center !important; gap: 12px; min-height: 56px; }
.fs-check-pills .elementor-icon-list-icon { width: 26px !important; height: 26px; flex: none; display: grid !important; place-items: center; padding: 0 !important; border-radius: 50%; background: #3299D5; }
.fs-check-pills .elementor-icon-list-icon i, .fs-check-pills .elementor-icon-list-icon svg { color: #fff !important; fill: #fff !important; font-size: 13px; width: 13px; height: 13px; }
@media (max-width: 767px) { .fs-check-pills .elementor-icon-list-items { grid-template-columns: minmax(0, 1fr); } }
/* Plain check list */
.fs-checks .elementor-icon-list-icon i, .fs-checks .elementor-icon-list-icon svg { color: var(--fs-sky); fill: var(--fs-sky); }
.fs-checks .elementor-icon-list-text { color: inherit; }

/* Framework block: stage tabs (Nested Tabs widget) */
.fs-stage-tabs .e-n-tabs-heading { gap: 10px; flex-wrap: wrap; }
.fs-stage-tabs .e-n-tab-title { border: 1px solid rgba(255, 255, 255, .35) !important; border-radius: 999px !important; background: transparent !important; padding: 10px 20px !important; }
.fs-stage-tabs .e-n-tab-title[aria-selected="true"] { background: #fff !important; border-color: #fff !important; }
.fs-stage-tabs .e-n-tab-title-text { font-family: var(--fs-font); font-weight: 800; font-size: 19px; letter-spacing: -.02em; color: #fff; }
.fs-stage-tabs .e-n-tab-title .fs-plogo { font-size: inherit; color: #fff; }
.fs-stage-tabs .e-n-tab-title[aria-selected="true"] .e-n-tab-title-text,
.fs-stage-tabs .e-n-tab-title[aria-selected="true"] .fs-plogo { color: #250762; }
.fs-stage-tabs .e-n-tab-title[aria-selected="true"] .fs-plogo b { color: #3299D5; }
.fs-stage-tabs .e-n-tab-title:hover { border-color: #fff !important; }
.fs-stage-tabs .e-n-tabs-content > .e-con { background: transparent; }

/* Quiz callout */

/* Gradient CTA banner above the footer */
.fs-cta-banner { border-radius: 40px; text-align: center; }  /* padding is set on the container */
.fs-cta-banner .elementor-heading-title { color: #fff; font-size: clamp(36px, 4.6vw, 64px); }
.fs-cta-banner .elementor-widget-text-editor { color: rgba(255, 255, 255, .92); font-size: 18px; }

/* Team cards */
.fs-team .elementor-image-box-img img { border-radius: 24px 24px 0 0; background: radial-gradient(260px 220px at 50% 100%, rgba(50, 153, 213, .9), transparent 70%), var(--fs-purple); }
.fs-team .elementor-image-box-title { color: var(--fs-purple); }
.fs-team .elementor-image-box-description { color: var(--fs-sky-ink); font-weight: 600; font-size: 15px; }

/* Value cards (purple, icon tile left) reuse fs-pcard */
/* Comparison / pricing tables reuse .fs-table in an HTML widget; wide tables scroll on phones */
.fs-table-wrap { overflow-x: auto; border-radius: 18px; box-shadow: var(--fs-shadow-card); }
.fs-table-wrap .fs-table { min-width: 760px; }
.fs-table td.us, .fs-table th.us { background: var(--fs-tint); }
.fs-table .no { color: #9B98B3; }

/* ---------- 19. Page template details ---------- */
.fs-trust-num .elementor-heading-title { color: #fff; line-height: 1; text-shadow: 0 0 22px rgba(255, 255, 255, .55), 0 0 4px rgba(255, 255, 255, .4); }
.fs-trust-num small, .fs-star { font-size: .55em; vertical-align: .55em; margin-left: 4px; color: var(--e-global-color-fsgold, #F4B400); text-shadow: none; }
.fs-identity { color: var(--fs-aqua); font-size: 17px; }
.fs-sig .elementor-heading-title { font-family: var(--fs-font); font-size: 20px; font-weight: 700; color: var(--fs-purple); margin: 0; }
.fs-dark .fs-sig .elementor-heading-title { color: #fff; }
.fs-belief .elementor-heading-title { max-width: 980px; margin-inline: auto; font-size: clamp(22px, 2.4vw, 32px); font-weight: 700; line-height: 1.35; color: #fff; }
.fs-mf-end .elementor-heading-title { font-size: clamp(20px, 2vw, 26px); font-weight: 700; color: #fff; }
.fs-price .elementor-heading-title { font-family: var(--fs-font); font-size: clamp(40px, 4vw, 56px); font-weight: 800; line-height: 1; color: var(--fs-purple); }
.fs-price .elementor-heading-title small { font-size: 18px; font-weight: 500; color: var(--fs-muted); }
.fs-dark .fs-price .elementor-heading-title, .fs-purple-card .fs-price .elementor-heading-title { color: #fff; }
.fs-dark .fs-price .elementor-heading-title small, .fs-purple-card .fs-price .elementor-heading-title small { color: #C9C6EA; }
.fs-k { font-family: var(--fs-font-ui); font-size: 12.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--fs-muted); margin: 0 0 6px; }
.fs-card-meta, .fs-card-meta p { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 0; font-family: var(--fs-font-ui); font-size: 14px; color: var(--fs-muted); }
.fs-crumbs { font-family: var(--fs-font-ui); font-size: 14px; color: var(--fs-muted); }
.fs-crumbs a { color: var(--fs-muted); text-decoration: none; }
.fs-crumbs a:hover { color: var(--fs-royal); text-decoration: underline; }
.fs-crumbs [aria-current] { color: var(--fs-purple); font-weight: 600; }
.fs-back { font-family: var(--fs-font-ui); font-size: 14.5px; font-weight: 600; color: var(--fs-sky-ink); text-decoration: none; }
.fs-back:hover { color: var(--fs-royal); }

/* Quote chip over a cut-out photo */
.fs-quote-chip { position: relative; max-width: 340px; margin: -70px 0 0 auto; padding: 16px 18px; border-radius: 14px; background: #fff; box-shadow: 0 16px 34px -18px rgba(28, 22, 72, .45); font-size: 15px; font-style: italic; color: var(--fs-ink); }
.fs-quote-chip cite { display: block; margin-top: 8px; font-size: 13px; font-style: normal; font-weight: 700; color: var(--fs-purple); }

/* Event / workshop dates and fact rows */
.fs-date { display: grid; place-items: center; width: 78px; padding: 10px 0; border-radius: 16px; background: var(--fs-grad); color: #fff; text-align: center; font-family: var(--fs-font); line-height: 1.1; }
.fs-date small { font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; }
.fs-date b { font-size: 30px; font-weight: 800; }
.fs-date span { font-size: 12px; opacity: .9; }
.fs-date--lg { display: flex; gap: 14px; align-items: center; width: auto; padding: 0; background: none; }
.fs-date--lg b { font-size: clamp(76px, 8vw, 104px); color: transparent; background: var(--fs-grad-text); -webkit-background-clip: text; background-clip: text; }
.fs-date--lg span { font-size: 26px; font-weight: 700; text-align: left; }
.fs-date--lg small { display: block; font-size: 15px; font-weight: 500; letter-spacing: 0; text-transform: none; color: #C9C6EA; }
.fs-facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; margin: 0; padding: 16px 0; border-block: 1px solid var(--fs-line); }
.fs-facts dt { font-family: var(--fs-font-ui); font-size: 12.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--fs-sky-ink); }
.fs-facts dd { margin: 4px 0 0; font-family: var(--fs-font-ui); font-size: 14px; color: var(--fs-muted); }
.fs-facts dd b { display: block; font-family: var(--fs-font); font-size: 16px; color: var(--fs-purple); }
.fs-facts--stack { grid-template-columns: minmax(0, 1fr); gap: 0; border: 0; padding: 0; }
.fs-facts--stack > div { padding: 10px 0; border-bottom: 1px solid var(--fs-line); }
.fs-facts--stack dd { font-family: var(--fs-font); font-size: 15.5px; font-weight: 600; color: var(--fs-purple); }
@media (max-width: 767px) { .fs-facts { grid-template-columns: minmax(0, 1fr); } }
.fs-countdown .elementor-countdown-item { background: rgba(255, 255, 255, .1) !important; border-radius: 16px; }
.fs-countdown .elementor-countdown-digits { font-family: var(--fs-font); font-weight: 800; color: #fff; }
.fs-countdown .elementor-countdown-label { color: #C9C6EA; }
.fs-agenda { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.fs-agenda li { display: grid; grid-template-columns: 84px minmax(0, 1fr) auto; gap: 16px; align-items: center; padding: 16px 20px; border-radius: 16px; background: #fff; box-shadow: 0 14px 30px -20px rgba(28, 22, 72, .45); }
.fs-agenda .t { font-family: var(--fs-font); font-size: 20px; font-weight: 800; color: var(--fs-sky-ink); }
.fs-agenda b { font-family: var(--fs-font); font-size: 17px; color: var(--fs-purple); }
.fs-agenda li.brk { background: transparent; box-shadow: none; border: 1.5px dashed #C9C8D3; }
.fs-agenda li.brk b { font-weight: 500; color: var(--fs-muted); }
@media (max-width: 767px) { .fs-agenda li { grid-template-columns: minmax(0, 1fr); gap: 4px; } }

/* Pillar page: "You are here" list and self-check */
.fs-here { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.fs-here a { display: grid; grid-template-columns: 40px minmax(0, 1fr); gap: 2px 14px; align-items: center; padding: 12px 16px; border-radius: 16px; border: 1px solid rgba(255, 255, 255, .22); text-decoration: none; }
.fs-here i { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 50%; background: rgba(255, 255, 255, .12); font-style: normal; font-weight: 800; color: #fff; }
.fs-here .fs-plogo { font-size: 22px; color: #fff; }
.fs-here i { grid-row: span 2; }
.fs-here small { grid-column: 2; display: block; font-family: var(--fs-font-ui); font-size: 13.5px; color: #C9C6EA; }
.fs-here li.on a { background: #fff; border-color: #fff; }
.fs-here li.on i { background: var(--fs-grad); }
.fs-here li.on small { color: var(--fs-muted); }
.fs-here li.on .fs-plogo { color: var(--fs-purple); }
.fs-selfcheck ul { list-style: none; margin: 0 0 18px; padding: 0; display: grid; gap: 10px; }
.fs-selfcheck label { display: flex; gap: 12px; align-items: flex-start; padding: 14px 16px; border: 2px solid var(--fs-line); border-radius: 14px; cursor: pointer; font-size: 16px; color: var(--fs-purple); }
.fs-selfcheck label:has(input:checked) { border-color: var(--fs-purple); background: var(--fs-tint); }
.fs-selfcheck input { width: 20px; height: 20px; margin-top: 2px; accent-color: var(--fs-royal); }
.fs-sc-result { padding: 24px; border-radius: 20px; background: var(--fs-glow), var(--fs-grad-purple); color: #fff; }
.fs-sc-result h3 { color: #fff !important; margin: 4px 0 6px; }
.fs-sc-result p { color: rgba(255, 255, 255, .9); }
.fs-sc-score b { font-family: var(--fs-font); font-size: 56px; font-weight: 800; color: #fff; }
.fs-sc-result .elementor-button { margin-top: 12px; background: #fff; color: var(--fs-purple); border-color: transparent; }

/* Case study: simple bar chart */
.fs-bars { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px; align-items: end; height: 260px; padding-top: 24px; }
.fs-bar { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; height: 100%; }
.fs-bar i { display: block; width: min(34px, 70%); border-radius: 4px 4px 0 0; background: var(--fs-sky); }
.fs-bar--base i { background: #B9B8C6; }
.fs-bar span { font: 700 13px var(--fs-font-ui); color: var(--fs-purple); margin-bottom: 4px; }
.fs-bar small { margin-top: 6px; font: 500 12px var(--fs-font-ui); color: var(--fs-muted); }

/* Articles */
.fs-prose { font-size: 17.5px; line-height: 1.75; color: var(--fs-body); }
.fs-prose h2 { margin: 46px 0 14px; font-size: clamp(26px, 2.6vw, 32px); color: var(--fs-purple); }
.fs-prose ul, .fs-prose ol { padding-left: 22px; }
.fs-prose li + li { margin-top: 8px; }
.fs-prose a { color: var(--fs-sky-ink); text-decoration: underline; }
.fs-dek { font-size: 20px; color: var(--fs-purple); }
.fs-callout { margin: 28px 0; padding: 22px 24px; border-radius: 18px; background: var(--fs-soft); }
.fs-callout b { display: block; font-family: var(--fs-font); font-size: 17px; color: var(--fs-purple); }
.fs-pull, .fs-pull .elementor-blockquote { margin: 30px 0; padding: 4px 0 4px 26px; border-left: 4px solid; border-image: var(--fs-grad) 1; font-family: var(--fs-font); font-size: clamp(20px, 2vw, 24px); font-weight: 600; line-height: 1.45; color: var(--fs-purple); }
.fs-pull cite, .fs-pull .elementor-blockquote__author { display: block; margin-top: 10px; font-family: var(--fs-font-ui); font-size: 14.5px; font-style: normal; font-weight: 500; color: var(--fs-muted); }
.fs-sample-content { position: relative; padding: 28px 22px 10px; border: 2px dashed #F2994A; border-radius: 16px; }
.fs-sample-content::before { content: "Sample article for design reference: delete this widget once Post Content shows a real post"; position: absolute; top: -12px; left: 16px; padding: 2px 10px; border-radius: 6px; background: #F2994A; color: #fff; font: 700 12px var(--fs-font-ui); }
.fs-toc .elementor-toc__header { background: none; border: 0; padding: 0 0 8px; }
.fs-toc .elementor-toc__header-title { font: 700 12.5px var(--fs-font-ui); letter-spacing: .08em; text-transform: uppercase; color: var(--fs-muted); }
.fs-toc .elementor-toc__list-item-text { font-family: var(--fs-font-ui); font-size: 14.5px; color: var(--fs-body); }
.fs-toc .elementor-toc__list-item-text.elementor-item-active { color: var(--fs-purple); font-weight: 700; }
.fs-byline .elementor-icon-list-text { font-family: var(--fs-font-ui); font-size: 14.5px; color: var(--fs-muted); }
.fs-chapters { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.fs-chapters li { display: grid; grid-template-columns: 64px minmax(0, 1fr); gap: 14px; padding: 12px 16px; border: 1px solid var(--fs-line); border-radius: 14px; font-family: var(--fs-font-ui); }
.fs-chapters span { font-weight: 700; color: var(--fs-sky-ink); }

/* Placeholders for embeds (GoHighLevel calendar, podcast player) */
.fs-embed-ph { display: grid; place-items: center; min-height: 220px; padding: 20px; border: 2px dashed #9FB7D9; border-radius: 16px; background: #EEF4FB; font-family: var(--fs-font-ui); font-size: 14px; text-align: center; color: var(--fs-royal); }

/* Team flip cards */

/* Small service rows in the framework tabs */
.fs-svc-row .elementor-image-box-wrapper { display: flex; align-items: center; gap: 14px; text-align: left; }
.fs-svc-row .elementor-image-box-img { width: 48px !important; margin: 0 !important; }
.fs-svc-row .elementor-image-box-title { margin: 0; font-size: 16px; }

/* Posts widget cards */
.fs-posts .elementor-post__card { border-radius: 24px; border: 0; box-shadow: var(--fs-shadow-card); }
.fs-posts .elementor-post__title a { font-family: var(--fs-font); color: var(--fs-purple); }
.fs-posts .elementor-post__badge { border-radius: 999px; background: var(--fs-sky); font-family: var(--fs-font); }
.fs-posts .elementor-post__read-more { font-family: var(--fs-font); font-style: italic; color: var(--fs-purple); text-decoration: underline; text-decoration-color: var(--fs-aqua); text-underline-offset: 6px; }
.fs-map iframe { border-radius: 20px; }

/* White cards sitting inside purple sections keep dark text */
:where(.fs-dark .fs-gcard:not(.fs-step-hl)) .elementor-heading-title,
:where(.fs-dark .fs-gcard:not(.fs-step-hl)) :is(h1, h2, h3, h4) { color: var(--fs-purple); }
:where(.fs-dark .fs-gcard:not(.fs-step-hl)) .elementor-widget-text-editor,
:where(.fs-dark .fs-gcard:not(.fs-step-hl)) .elementor-widget-html,
:where(.fs-dark .fs-gcard:not(.fs-step-hl)) .elementor-icon-list-text,
:where(.fs-dark .fs-gcard:not(.fs-step-hl)) .elementor-image-box-description { color: var(--fs-body); }
:where(.fs-dark .fs-gcard .fs-eyebrow) .elementor-heading-title { color: var(--fs-sky); }
.fs-dark .fs-gcard .fs-link-u .elementor-button, .fs-dark .fs-gcard .fs-link-u a { color: var(--fs-purple) !important; }
:where(.fs-dark .fs-gcard) .fs-soft-box { color: var(--fs-ink); }
:where(.fs-dark .fs-gcard) .elementor-image-box-title { color: var(--fs-purple); }
.fs-dark .fs-gcard .fs-step-num .elementor-heading-title { color: transparent; }

/* ---------- 20. Media details (resource cards, DIY resources, coaching) ---------- */
/* Resource card media header: card container gets fs-rcard; media is the first child */
.fs-rcard { overflow: hidden; }
.fs-rmedia { position: relative; height: 172px; overflow: hidden; display: flex; align-items: center; justify-content: center; }
.e-con.fs-rmedia { --min-height: 172px; min-height: 172px; }
.fs-rm-blog { background: linear-gradient(135deg, #EAF4FB, #DDEBF7); }
.fs-rm-blog .fs-art { width: 74px; height: 74px; border-radius: 18px; display: grid; place-items: center; background: var(--fs-purple); color: #fff; box-shadow: 0 14px 24px -12px rgba(37, 7, 98, .6); }
.fs-rm-case { flex-direction: column; align-items: flex-start; padding: 0 26px; color: #fff; background: radial-gradient(260px 180px at 100% 100%, rgba(78, 152, 216, .7), transparent 70%), var(--fs-purple); }
.fs-rm-case b { font-weight: 800; font-size: 46px; line-height: 1; color: #8ED8F0; }
.fs-rm-case span { margin-top: 6px; font-size: 14.5px; }
.fs-rm-pod { gap: 18px; padding: 0 24px; justify-content: flex-start; background: linear-gradient(135deg, var(--fs-aqua), var(--fs-sky) 45%, var(--fs-royal)); }
.e-con.fs-rm-vid { background-color: var(--fs-purple-deep); background-position: 50% 15% !important; }
.e-con.fs-rm-vid::before { content: ""; position: absolute; inset: 0; background: rgba(26, 4, 70, .45); }
.fs-rm-vid > .elementor-widget { position: static; }
.fs-rplay { position: relative; z-index: 1; flex: none; width: 58px; height: 58px; border-radius: 50%; display: grid; place-items: center; background: #fff; color: var(--fs-purple); box-shadow: 0 10px 20px -8px rgba(0, 0, 0, .45); }
.fs-rplay svg { margin-left: 3px; }
.fs-rdur { position: absolute; z-index: 1; right: 12px; bottom: 12px; padding: 3px 8px; border-radius: 6px; background: rgba(0, 0, 0, .75); color: #fff; font-family: var(--fs-font-ui); font-size: 12px; font-weight: 600; }

/* ---------- 16. Accessibility ---------- */
@media (prefers-reduced-motion: reduce) {
  .elementor-button, .fs-gcard--hover { transition: none; }
  .elementor-button:hover, .fs-gcard--hover:hover { transform: none; }
}

/* ---------- 21. Edge overlaps (final call to action, overlapping buttons) ---------- */
/* Final CTA: the card is pulled up into the section above (margin set in Elementor);
   below the overlap the footer purple shows behind it. */
.fs-final { background: linear-gradient(to bottom, transparent 110px, var(--fs-purple) 110px); }
.fs-cta-banner { box-shadow: 0 30px 60px -30px rgba(29, 30, 74, .6); }
.fs-cta-banner .elementor-button { border: 2px solid #4AA6DC; }
.fs-overlap { pointer-events: none; }
.fs-overlap .elementor-button { pointer-events: auto; }

/* ---------- 22. Service / stage problem section ---------- */
/* Numbered problem cards (container fs-pcard fs-pcard-n; padding set in Elementor) */
.fs-num-tile { display: grid; place-items: center; width: 72px; height: 72px; flex: none; border-radius: 16px; background: #fff;
  box-shadow: 0 0 0 4px var(--fs-sky), 0 0 20px 4px rgba(50, 153, 213, .55); font-family: var(--fs-font); font-weight: 800; font-size: 34px; line-height: 1; color: var(--fs-purple); }
.fs-pcard-n .elementor-heading-title { color: #fff; }
.fs-pcard-n .elementor-widget-text-editor { color: rgba(255, 255, 255, .92); }
/* Left card: service icon in a gradient tile, or the stage number */
.fs-art-tile img { width: 150px; height: 150px; padding: 26px; border-radius: 36px; background: var(--fs-grad-diag); box-shadow: 0 24px 40px -18px rgba(46, 77, 165, .7); object-fit: contain; }
.fs-art-num { display: grid; place-items: center; width: 150px; height: 150px; margin: 0 auto; border-radius: 36px; background: var(--fs-grad-diag);
  box-shadow: 0 24px 40px -18px rgba(46, 77, 165, .7); font-family: var(--fs-font); font-weight: 800; font-size: 76px; line-height: 1; color: #fff; }
/* "Covers / Deliverables / Platforms" bar under the included grid (Text Editor: fs-platforms) */
.fs-platforms { margin-top: 14px; padding: 20px 28px; border-radius: 10px; background: var(--fs-purple); box-shadow: 0 16px 28px -14px rgba(46, 77, 165, .6); }
.fs-platforms b { font-style: normal; font-weight: 600; }

/* ---------- 23. Full-width sections ----------
   With Page Layout "Elementor Full Width" this does nothing. With the theme's default (boxed) layout it lets
   every top-level section run edge to edge, like the HTML. */
html, body { overflow-x: clip; }
body:not(.elementor-template-full-width):not(.elementor-template-canvas) :is(.elementor[data-elementor-type="wp-page"], .elementor[data-elementor-type="wp-post"], .elementor[data-elementor-type="single-post"], .elementor[data-elementor-type="single-page"], .elementor[data-elementor-type="single"]) > .e-con.e-parent {
  --width: 100vw; width: 100vw; max-width: 100vw; margin-left: calc(50% - 50vw); margin-right: calc(50% - 50vw);
}
/* HTML components (exact copies of interactive parts of the design) sit above the next section when they overlap it */
.elementor-widget-html:has(.fsx) { position: relative; z-index: 3; }
/* Stats band: numbers left-aligned with thin dividers, as in the HTML */
.fs-stats .elementor-counter { align-items: flex-start; text-align: left; }
.fs-stats .elementor-counter-number-wrapper { justify-content: flex-start; }
.fs-stats .e-con-inner > .e-con > .e-con:not(:first-child), .fs-stats > .e-con > .e-con > .e-con:not(:first-child) { border-left: 1px solid rgba(255, 255, 255, .45); padding-left: 24px; }
@media (max-width: 767px) { .fs-stats .e-con .e-con:not(:first-child) { border-left: 0; padding-left: 0; border-top: 1px solid rgba(255, 255, 255, .45); padding-top: 24px; } }

/* ---------- 24. Footer details ---------- */
/* faint "first search" wordmark in the bottom-right of the footer */
.fs-footer { position: relative; overflow: hidden; }
.fs-footer::after { content: "first search"; position: absolute; z-index: 0; right: -20px; bottom: -30px; font-family: var(--fs-font); font-weight: 800;
  font-size: clamp(90px, 15vw, 230px); line-height: 1; letter-spacing: -0.05em; color: rgba(255, 255, 255, .035); pointer-events: none; white-space: nowrap; }
.fs-footer > .e-con-inner, .fs-footer > .e-con { position: relative; z-index: 1; }
/* "We put your business first." - gradient words */
.fs-footer .fs-tagline .fs-gt { background: var(--fs-grad-text); -webkit-background-clip: text; background-clip: text; color: transparent; }
/* contact list: white icons on gradient tiles */
.fs-ct .elementor-icon-list-item { align-items: center !important; }
.fs-ct .elementor-icon-list-icon { width: 38px !important; height: 38px; flex: none; display: grid !important; place-items: center; border-radius: 12px; background: var(--fs-grad-diag); }
.fs-ct .elementor-icon-list-icon i, .fs-ct .elementor-icon-list-icon svg { color: #fff !important; fill: #fff !important; font-size: 17px; width: 17px; height: 17px; }
.fs-ct .elementor-icon-list-text { font-family: var(--fs-font-ui); font-size: 15.5px; color: rgba(255, 255, 255, .86) !important; }
/* social icons: translucent circles, gradient on hover */
.fs-social .elementor-social-icon { transition: background .2s ease, transform .2s ease; }
.fs-social .elementor-social-icon:hover { background: var(--fs-grad-diag) !important; transform: translateY(-2px); }
/* newsletter: email field and button on one line */
.fs-news-form .elementor-field-group { margin-bottom: 0 !important; }
.fs-news-form .elementor-field-textual { min-height: 50px; padding: 0 16px; border-radius: 12px; border: 1px solid rgba(255, 255, 255, .3) !important; background: rgba(255, 255, 255, .95); font-family: var(--fs-font-ui); font-size: 16px; color: var(--fs-ink); }
.fs-news-form .elementor-button { min-height: 50px; padding: 12px 20px; font-size: 16px; white-space: nowrap; border-color: transparent; background: var(--fs-grad); }
.fs-footer .fs-news .elementor-heading-title { white-space: nowrap; }
.fs-news-form .elementor-form-fields-wrapper { display: flex !important; flex-wrap: nowrap; gap: 10px; margin: 0 !important; }
.fs-news-form .elementor-form-fields-wrapper > .elementor-field-group { width: auto !important; max-width: none !important; padding: 0 !important; margin: 0 !important; }
.fs-news-form .elementor-form-fields-wrapper > .elementor-field-group:not(.elementor-field-type-submit) { flex: 1 1 auto; min-width: 0; }
.fs-news-form .elementor-field-type-submit { flex: none; }
.fs-news-form .elementor-field-label { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
@media (max-width: 767px) { .fs-news-form .elementor-form-fields-wrapper { flex-wrap: wrap; } .fs-news-form .elementor-form-fields-wrapper > .elementor-field-group { flex: 1 1 100%; } }
.fs-footer .fs-bottom a { text-decoration: none !important; margin-left: 16px; }

/* ---------- 25. Footer link hover: white text + gradient underline (as the header menu) ---------- */
.fs-footer .elementor-icon-list-item > a { text-decoration: none !important; }
.fs-footer .elementor-icon-list-item > a .elementor-icon-list-text,
.fs-footer .fs-bottom a {
  position: relative; display: inline-block; padding-bottom: 3px; transition: color .15s ease;
}
.fs-footer .elementor-icon-list-item > a .elementor-icon-list-text::after,
.fs-footer .fs-bottom a::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; border-radius: 2px; background: var(--fs-grad);
  transform: scaleX(0); transform-origin: left; transition: transform .2s ease; pointer-events: none;
}
.fs-footer .elementor-icon-list-item > a:hover .elementor-icon-list-text,
.fs-footer .elementor-icon-list-item > a:focus-visible .elementor-icon-list-text,
.fs-footer .fs-bottom a:hover, .fs-footer .fs-bottom a:focus-visible { color: #fff !important; text-decoration: none !important; }
.fs-footer .elementor-icon-list-item > a:hover .elementor-icon-list-text::after,
.fs-footer .elementor-icon-list-item > a:focus-visible .elementor-icon-list-text::after,
.fs-footer .fs-bottom a:hover::after, .fs-footer .fs-bottom a:focus-visible::after { transform: scaleX(1); }
/* stage logos in the footer: gentle fade on hover, as in the design */
.fs-footer .fs-stage-links a { transition: opacity .15s ease; }
.fs-footer .fs-stage-links a:hover { opacity: .85; }

/* ---------- 26. Home page details ---------- */
/* How it works: the big gradient numbers sit above each card (positioned on the widget, so Elementor's wrappers can't move them) */
.fs-step > .elementor-element.fs-step-num { position: absolute !important; top: -92px; left: 50%; transform: translateX(-50%); z-index: 2; width: auto !important; max-width: none !important; margin: 0 !important; }
.fs-step-num .elementor-heading-title { position: static !important; transform: none !important; top: auto !important; left: auto !important;
  font-size: 120px !important; font-weight: 800 !important; line-height: 1 !important; letter-spacing: -0.04em !important; text-align: center;
  color: transparent !important; background: linear-gradient(180deg, #5FB0E6, #4E98D8 60%, #3B6FC0); -webkit-background-clip: text; background-clip: text;
  filter: drop-shadow(0 6px 10px rgba(0, 0, 0, .25)); }
@media (max-width: 767px) { .fs-step > .elementor-element.fs-step-num { top: -70px; } .fs-step-num .elementor-heading-title { font-size: 90px !important; } }
/* FAQ: the +/- button stays a perfect circle */
.fs-faq .elementor-accordion-icon, .fs-faq .elementor-toggle-icon { width: 56px !important; height: 56px !important; min-width: 56px; max-height: 56px; align-self: center; aspect-ratio: 1 / 1; line-height: 0 !important; padding: 0 !important; }
@media (max-width: 767px) { .fs-faq .elementor-accordion-icon, .fs-faq .elementor-toggle-icon { width: 42px !important; height: 42px !important; min-width: 42px; max-height: 42px; } }
/* small script-only HTML widgets (e.g. the count-up) take no space */
.elementor-widget.fs-hidden-script { position: absolute !important; width: 0 !important; height: 0 !important; overflow: hidden; margin: 0 !important; }

/* FAQ: open question title in white on the purple bar */
.fs-faq .elementor-tab-title.elementor-active .elementor-accordion-title,
.fs-faq .elementor-tab-title.elementor-active .elementor-toggle-title { color: #fff !important; }
/* How it works: the last card is the gradient card, with white text */
.fs-step.fs-step-hl { background: var(--fs-grad-diag) border-box !important; background-origin: border-box !important; background-clip: border-box !important; border-color: transparent !important; }
.fs-step.fs-step-hl .elementor-heading-title:not(.fs-step-num *), .fs-step.fs-step-hl .elementor-widget-text-editor { color: #fff; }

/* ---------- 27. Results table (Essential Addons Data Table: add fs-dtable) ----------
   Cell CSS classes: m = metric name, b = before, ar = arrow, a = after (gradient column). Measured from the design. */
.fs-dtable .eael-data-table-wrap { overflow-x: auto; border-radius: 14px; }
.fs-dtable table.eael-data-table { width: 100% !important; margin: 0 !important; border-collapse: separate !important; border-spacing: 0; border: 0 !important;
  border-radius: 14px; overflow: hidden; background: #fff !important; table-layout: auto; }
.fs-dtable table.eael-data-table th, .fs-dtable table.eael-data-table td {
  border: 0 !important; border-bottom: 1px solid #D9D8D7 !important; border-right: 1px solid #D9D8D7 !important; background: #fff !important;
  color: var(--fs-purple) !important; font-family: var(--fs-font) !important; text-transform: none !important; letter-spacing: normal !important; vertical-align: middle; }
.fs-dtable table.eael-data-table th:last-child, .fs-dtable table.eael-data-table td:last-child { border-right: 0 !important; }
/* header row */
.fs-dtable table.eael-data-table thead th { padding: 14px 16px 10px !important; font-size: 14px !important; font-weight: 600 !important; text-align: left !important;
  border-bottom: 2px solid #3299D5 !important; }
.fs-dtable table.eael-data-table thead th.b { background: var(--fs-purple) !important; color: #fff !important; border-right-color: rgba(255, 255, 255, .18) !important; }
.fs-dtable table.eael-data-table thead th.ar { background: #ECECEC !important; color: #fff !important; border-right-color: rgba(255, 255, 255, .18) !important; }
.fs-dtable table.eael-data-table thead th.a { background: var(--fs-grad) !important; color: #fff !important; }
/* body rows */
.fs-dtable table.eael-data-table tbody td { padding: 12px 16px !important; }
.fs-dtable table.eael-data-table td.m { background: #ECECEC !important; font-size: 22px !important; font-weight: 600 !important; text-align: left !important; }
.fs-dtable table.eael-data-table td.b { font-size: 17px !important; font-weight: 600 !important; text-align: center !important; }
.fs-dtable table.eael-data-table td.ar { background: #ECECEC !important; color: #3299D5 !important; font-size: 20px !important; font-weight: 700 !important; text-align: center !important; }
.fs-dtable table.eael-data-table td.a { background: var(--fs-grad) !important; color: #fff !important; font-size: 17px !important; font-weight: 800 !important; text-align: center !important;
  border-bottom-color: rgba(255, 255, 255, .35) !important; }
.fs-dtable table.eael-data-table td .td-content-wrapper, .fs-dtable table.eael-data-table td .td-content { display: block; text-align: inherit !important; color: inherit !important; font: inherit; }
.fs-dtable table.eael-data-table tbody tr:last-child td { border-bottom: 0 !important; }
@media (max-width: 767px) {
  .fs-dtable table.eael-data-table tbody td { padding: 10px 8px !important; }
  .fs-dtable table.eael-data-table td.m { font-size: 16px !important; }
  .fs-dtable table.eael-data-table td.b, .fs-dtable table.eael-data-table td.a { font-size: 15px !important; }
  .fs-dtable table.eael-data-table thead th { padding: 10px 8px 8px !important; font-size: 12px !important; }
  .fs-dtable table.eael-data-table td.ar { padding: 10px 2px !important; }
}

/* ---------- 28. Google review cards (Essential Addons Testimonial: add fs-testi; card container: fs-gcard fs-review-card) ---------- */
.fs-review-card { border-radius: 38px !important; }
.fs-testi .eael-testimonial-item { position: static; text-align: left; }
.fs-testi .testimonial-star-rating { display: flex; gap: 3px; margin: 0 0 12px !important; padding: 0 !important; }
.fs-testi .testimonial-star-rating li { display: block; margin: 0; padding: 0; line-height: 1; }
.fs-testi .testimonial-star-rating li i, .fs-testi.elementor-widget .rating-five .testimonial-star-rating li i { color: #F4B400 !important; font-size: 19px; }
.fs-testi .eael-testimonial-content { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; margin: 0 !important; padding: 0 !important; }
.fs-testi .eael-testimonial-content .eael-testimonial-text { flex: 0 0 100%; margin: 0 0 14px !important; font-family: var(--fs-font); font-size: 16.5px !important; font-style: normal !important;
  line-height: 1.55 !important; color: var(--fs-body) !important; }
.fs-testi .eael-testimonial-text p { margin: 0; }
.fs-testi .eael-testimonial-content .eael-testimonial-user { display: inline-flex !important; align-items: center; gap: 10px; float: none !important; margin: 0 !important; white-space: nowrap;
  font-family: var(--fs-font) !important; font-size: 16px !important; font-style: normal !important; font-weight: 600 !important; line-height: 1.4 !important; color: var(--fs-purple) !important; }
.fs-testi .eael-testimonial-user::after { content: "\00B7"; font-family: var(--fs-font-ui); font-size: 14.5px; font-weight: 400; color: var(--fs-muted); }
.fs-testi .eael-testimonial-content .eael-testimonial-user-company { display: inline-flex !important; align-items: center; gap: 10px; margin: 0 !important;
