/* Team (fs-team-grid > fs-tm-col > Flip Box with fs-team-card): 3 on top, 2 centred below */
.fs-team-grid > .fs-tm-col { flex: 0 0 calc((100% - 56px) / 3) !important; width: auto !important; min-width: 0; }
.fs-team-card .elementor-flip-box { height: 460px !important; border-radius: 30px; perspective: 1000px; transform-style: preserve-3d; }
/* The navy + glow behind the photo turns together with the front face (1px behind it) and hides once it faces away,
   so nothing static sits in the card's plane to cut the turning face in half. */
.fs-team-card .elementor-flip-box::before { content: ""; position: absolute; inset: 0; border-radius: 30px; pointer-events: none;
  background: radial-gradient(260px 220px at 50% 300px, rgba(50, 153, 213, .9), transparent 70%), var(--fs-purple);
  box-shadow: 0 20px 40px -24px rgba(28, 22, 72, .55); transform: rotateY(0deg) translateZ(-1px);
