.fs-team-card.elementor-flip-box--direction-right .elementor-flip-box:hover::before { transform: rotateY(180deg) translateZ(-1px); }
.fs-team-card .elementor-flip-box__layer { transition: transform .7s cubic-bezier(.3, .7, .3, 1) !important; }
